#include <bits/stdc++.h>
using namespace std;
#define int long long


int32_t main() {
	// your code goes here
	int tt;cin>>tt;
	while(tt--){
	    int n;cin>>n;
	    vector<int> a(3*n);
	    for(int i=0;i<3*n;i++) cin>>a[i];
	    sort(a.rbegin(),a.rend());
	    vector<int> pfx(3*n+1);
	    for(int i=1;i<=3*n;i++) pfx[i]=pfx[i-1]+a[i-1];
	    int res=0;
	    for(int x=0;x<=n;x++){
	       // for(int y=0;y<=n-x;y++){
	       //     int z=n-x-y;
	       //     int curr=pfx[x]*6;
	       //     curr+=(pfx[x+2*y]-pfx[x])*4;
	       //     curr+=(pfx[x+2*y+3*z]-pfx[x+2*y])*3;
	       //    // cout<<x<<" "<<y<<" "<<z<<" "<<curr<<endl;
	       //     res=max(res,curr);
	       // }
	       
	       //all 4
	       int m=n-x;
	       int curr=pfx[x]*2+pfx[x+2*m]*4;
	       res=max(res,curr);
	       int l=0,r=m-1;
	       int mid=(l+r)/2;
	       if(r<0) continue;
	       while(l<r){
	           int mid=(l+r+1)/2;
	           int s1=pfx[x+2*m-2*mid]-pfx[x+2*m-2*mid-2];
	           int s2=pfx[x+2*m+mid+1]-pfx[x+2*m+mid];
	           //cout<<x<<" "<<mid<<" "<<s1<<" "<<s2<<endl;
	           if(3*s2>=s1) l=mid;
	           else r=mid-1;
	       }
	       int y=m-l-1;
	       int z=n-x-y;
	       //cout<<x<<" "<<l<<" "<<mid<<endl;
	       curr=pfx[x]*2+pfx[x+2*y]+pfx[x+2*y+3*z]*3;
	       res=max(res,curr);
	    }
	    cout<<res<<endl;
	}
}
